#pragma once

#include "src/base/base.h"
#include "src/base/serialization.h"
#include "src/raft/entry.h"
#include "src/raft/raft_state.h"
#include "src/raft/wal_types.h"

// An Entry carries a WalCommand (generated by the primary). AppendEntries carries the leader's
// ledger records (docs/ledger.md: each entry with its WAL bytes), byte for byte, as the attached
// bytes; InstallSnapshot carries the leader's first ledger file, in chunks.

struct RequestElection {
  std::tuple<RaftTerm, RaftIndex> last_entry;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & last_entry;
  }
};

struct RequestElectionResponse {
  bool success;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & success;
  }
};

struct RequestVote {
  std::tuple<RaftTerm, RaftIndex> last_entry;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & last_entry;
  }
};

struct RequestVoteResponse {
  bool vote_granted;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & vote_granted;
  }
};

/// PreVote (Raft thesis §9.6): would the peer vote for the sender in the request's term (the
/// sender's term + 1)? Nothing changes on either side, the terms included; the sender starts a real
/// election only with a majority of yeses. A peer says no while it hears from a leader, so a node
/// that was cut off or stalled for a while doesn't depose a healthy leader (a PostgreSQL failover)
/// when it comes back.
struct RequestPreVote {
  std::tuple<RaftTerm, RaftIndex> last_entry;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & last_entry;
  }
};

struct RequestPreVoteResponse {
  bool granted;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & granted;
  }
};

struct AppendEntries {
  RaftTerm  prev_log_term;
  RaftIndex prev_log_idx;

  RaftIndex commit_idx;

  /// The number of records in the attached bytes (prev_log_idx + 1 on).
  uint64_t n = 0;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & prev_log_term;
    ar & prev_log_idx;
    ar & commit_idx;
    ar & n;
  }
};

struct AppendEntriesResponse {
  /** true if follower contained entry matching prev_log_idx and prev_log_term */
  bool success;

  /**
   * On success it is the index of the last entry.
   * Otherwise the min of prev_log_idx and the index of the last entry.
   */
  RaftIndex idx;

  /** The term at the idx. */
  std::optional<RaftTerm> term;

  /** n or more entries with the same term (and not committed). */
  std::optional<uint64_t> n;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & success;
    ar & idx;
    ar & term;
    ar & n;
  }
};

/// A chunk of the leader's first ledger file (docs/ledger.md §6.6): the attached bytes are
/// [offset, offset + their size) of the file that starts at |first|, whose bytes [0, size) the
/// leader sends, in order. The follower writes them to its install file and, after the last one,
/// replaces its ledger with it: the file header holds the state at the entry before the file's
/// first record, and the records the WAL. The WAL before them comes from a PostgreSQL backup (see
/// RaftState::needs_backup): the leader keeps every entry from the latest backup on
/// (RaftServer::set_wal_keep_from), so that backup and this file meet.
struct InstallSnapshot {
  RaftIndex first;
  uint64_t  offset = 0;
  uint64_t  size   = 0;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & first;
    ar & offset;
    ar & size;
  }
};

struct InstallSnapshotResponse {
  /** The last index of the follower's ledger, once the file is installed (done). */
  RaftIndex idx;

  bool success;

  /** The last chunk was received and installed. */
  bool done = false;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & idx;
    ar & success;
    ar & done;
  }
};

struct RequestResponseInfo {
  /* The epoch when the request got created. Useful to track round trip timing. */
  uint32_t epoch;

  /* The term that the server sent. */
  RaftTerm request_term;

  /* Index into outstanding requests array. */
  uint16_t request_idx;

  /* The request sequence. */
  uint32_t request_seq;

  /* log */
  bool log;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & epoch;
    ar & request_term;
    ar & request_idx;
    ar & request_seq;
    ar & log;
  }
};

struct RaftRequest {
  /* The current term in the server. */
  RaftTerm term;

  /* Node that generated the request. */
  RaftNodeId node_id;

  std::variant<std::monostate,
               RequestVote,
               AppendEntries,
               InstallSnapshot,
               RequestElection,
               RequestPreVote>
      request;

  /* Copied from request to associated response. */
  RequestResponseInfo info;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & term;
    ar & node_id;
    ar & request;
    ar & info;
  }
};

struct RaftResponse {
  /** currentTerm, to force other leader/candidate to step down */
  RaftTerm term;

  /** The node that generated the response. */
  RaftNodeId node_id;

  /** the response. */
  std::variant<std::monostate,
               RequestVoteResponse,
               AppendEntriesResponse,
               InstallSnapshotResponse,
               RequestElectionResponse,
               RequestPreVoteResponse>
      response;

  /* Copied from request to associated response. */
  RequestResponseInfo info;

  template <class Archive>
  void serialize(Archive& ar, unsigned int const /*version*/) {
    ar & term;
    ar & node_id;
    ar & response;
    ar & info;
  }
};

// Formatters

template <>
struct std::formatter<RequestElection> : public parse_fn {
  auto format(RequestElection const& r, std::format_context& ctx) const {
    return std::format_to(ctx.out(),
                          "RequestElection {{ term = {} index = {} }}",
                          std::get<RaftTerm>(r.last_entry),
                          std::get<RaftIndex>(r.last_entry));
  }
};

template <>
struct std::formatter<RequestElectionResponse> : public parse_fn {
  auto format(RequestElectionResponse const& r, std::format_context& ctx) const {
    return std::format_to(ctx.out(), "RequestElectionResponse {{ success = {} }}", r.success);
  }
};

template <>
struct std::formatter<RequestVote> : public parse_fn {
  auto format(RequestVote const& r, std::format_context& ctx) const {
    return std::format_to(ctx.out(),
                          "RequestVote {{ term = {} index = {} }}",
                          std::get<RaftTerm>(r.last_entry),
                          std::get<RaftIndex>(r.last_entry));
  }
};

template <>
struct std::formatter<RequestVoteResponse> : public parse_fn {
  auto format(RequestVoteResponse const& r, std::format_context& ctx) const {
    return std::format_to(ctx.out(), "RequestVoteResponse {{ vote_granted = {} }}", r.vote_granted);
  }
};

template <>
struct std::formatter<RequestPreVote> : public parse_fn {
  auto format(RequestPreVote const& r, std::format_context& ctx) const {
    return std::format_to(ctx.out(),
                          "RequestPreVote {{ term = {} index = {} }}",
                          std::get<RaftTerm>(r.last_entry),
                          std::get<RaftIndex>(r.last_entry));
  }
};

template <>
struct std::formatter<RequestPreVoteResponse> : public parse_fn {
  auto format(RequestPreVoteResponse const& r, std::format_context& ctx) const {
    return std::format_to(ctx.out(), "RequestPreVoteResponse {{ granted = {} }}", r.granted);
  }
};

template <>
struct std::formatter<AppendEntries> : public parse_fn {
  auto format(AppendEntries const& ae, std::format_context& ctx) const {
    return std::format_to(ctx.out(),
                          "AppendEntries {{ prev_log_idx = {} prev_log_term = {} commit_idx = {} "
                          "records = {} }}",
                          ae.prev_log_idx,
                          ae.prev_log_term,
                          ae.commit_idx,
                          ae.n);
  }
};

template <>
struct std::formatter<AppendEntriesResponse> : public parse_fn {
  auto format(AppendEntriesResponse const& r, std::format_context& ctx) const {
    if (r.success)
      return std::format_to(
          ctx.out(), "AppendEntriesResponse {{ success = true idx = {} }}", r.idx);

    auto out = std::format_to(ctx.out(), "AppendEntriesResponse {{ idx = {}", r.idx);
    if (r.term)
      out = std::format_to(out, " term = {}", *r.term);
    if (r.n)
      out = std::format_to(out, " n = {}", *r.n);
    return std::format_to(out, " }}");
  }
};

template <>
struct std::formatter<InstallSnapshot> : public parse_fn {
  auto format(InstallSnapshot const& s, std::format_context& ctx) const {
    return std::format_to(ctx.out(),
                          "InstallSnapshot {{ first = {} offset = {} size = {} }}",
                          s.first,
                          s.offset,
                          s.size);
  }
};

template <>
struct std::formatter<InstallSnapshotResponse> : public parse_fn {
  auto format(InstallSnapshotResponse const& s, std::format_context& ctx) const {
    return std::format_to(ctx.out(),
                          "InstallSnapshotResponse {{ success = {} done = {} idx = {} }}",
                          s.success,
                          s.done,
                          s.idx);
  }
};

template <>
struct std::formatter<RaftRequest> : public parse_fn {
  auto format(RaftRequest const& r, std::format_context& ctx) const {
    return std::format_to(ctx.out(),
                          "RaftRequest {{ {}:{} term = {} {} }}",
                          r.info.epoch,
                          r.info.request_seq,
                          r.term,
                          r.request);
  }
};

template <>
struct std::formatter<RaftResponse> : public parse_fn {
  auto format(RaftResponse const& r, std::format_context& ctx) const {
    return std::format_to(ctx.out(),
                          "RaftResponse {{ {}:{} term = {} {} }}",
                          r.info.epoch,
                          r.info.request_seq,
                          r.term,
                          r.response);
  }
};
